@@ -0,0 +1,25 @@
+// Sites: each location belongs to one site, and batches belong to the site of
+// their location. Items, suppliers, recipes and dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = store.data.sites.find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** Whether a batch lies in `site` (always true when `site` is undefined). */
+export function inSite(store, batch, site) {
+  if (site === undefined) return true;
+  return store.data.locations.some((l) => l.id === batch.location && l.site === site);
+}
+
+/** The location, or AppError unknown_location when it is not in `site`. */
+export function getLocation(store, id, site) {
+  const loc = store.data.locations.find((l) => l.id === id && (site === undefined || l.site === site));
+  if (!loc) throw new AppError("unknown_location", { id });
+  return loc;
+}
